import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import './App.css'
import { Breadcrumbs } from './graph/Breadcrumbs.tsx'
import { GraphCanvas, type GraphCanvasHandle, type ViewRequest } from './graph/GraphCanvas.tsx'
import { GraphLayout } from './graph/layout.ts'
import { Outline } from './graph/Outline.tsx'
import {
  buildIndex,
  childCounts,
  collapseNode,
  descendantIds,
  describeCounts,
  folderExists,
  folderToPathname,
  parsePathname,
  pruneIds,
  refId,
  revealFolder,
  sameRef,
  visibleGraph,
  type Entry,
  type FolderRef,
  type GraphNode,
  type ParsedLocation,
  type TreeIndex,
} from './graph/model.ts'

type Data =
  | { status: 'loading' }
  | { status: 'error'; message: string }
  | { status: 'ready'; index: TreeIndex; refreshing: boolean; refreshError: string | null }

type Mode = 'graph' | 'outline'

async function fetchEntries(signal?: AbortSignal): Promise<Entry[]> {
  const response = await fetch('/api/entries', { signal })
  let body: unknown = null
  try { body = await response.json() } catch { /* not JSON */ }
  const record = body && typeof body === 'object' ? (body as Record<string, unknown>) : null
  if (!response.ok) {
    throw new Error(typeof record?.error === 'string' ? record.error : `The API responded with status ${response.status}.`)
  }
  if (!record || !Array.isArray(record.entries)) throw new Error('The API returned an unexpected response.')
  return record.entries as Entry[]
}

function errorMessage(error: unknown): string {
  return error instanceof Error && error.message && error.name !== 'TypeError'
    ? error.message
    : 'The API could not be reached. Check that it is running.'
}

function summary(index: TreeIndex): string {
  let directories = 0
  let files = 0
  for (const node of index.nodes.values()) {
    if (node.kind === 'directory') directories += 1
    else if (node.kind === 'file') files += 1
  }
  return `${directories} ${directories === 1 ? 'folder' : 'folders'} and ${files} ${files === 1 ? 'Markdown file' : 'Markdown files'}`
}

const reducedMotionQuery = '(prefers-reduced-motion: reduce)'

function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = useState(() => window.matchMedia(reducedMotionQuery).matches)
  useEffect(() => {
    const query = window.matchMedia(reducedMotionQuery)
    const update = () => setReduced(query.matches)
    query.addEventListener('change', update)
    return () => query.removeEventListener('change', update)
  }, [])
  return reduced
}

function App() {
  const reducedMotion = usePrefersReducedMotion()
  const [layout] = useState(() => new GraphLayout({ synchronous: reducedMotion }))
  useEffect(() => { layout.setSynchronous(reducedMotion) }, [layout, reducedMotion])
  useEffect(() => () => layout.dispose(), [layout])

  const [data, setData] = useState<Data>({ status: 'loading' })
  const [expanded, setExpanded] = useState<ReadonlySet<string>>(() => new Set())
  const [location, setLocation] = useState<ParsedLocation>(() => parsePathname(window.location.pathname))
  const [mode, setMode] = useState<Mode>('graph')
  const [announcement, setAnnouncement] = useState('')
  const [viewRequest, setViewRequest] = useState<ViewRequest | null>(null)
  const canvasRef = useRef<GraphCanvasHandle>(null)
  const requestToken = useRef(0)
  // Mirrors of state for event handlers that must not re-subscribe on every change.
  const locationRef = useRef(location)
  const indexRef = useRef<TreeIndex | null>(null)
  useEffect(() => { locationRef.current = location }, [location])
  useEffect(() => { indexRef.current = data.status === 'ready' ? data.index : null }, [data])

  const requestView = useCallback((request: { type: 'fit' } | { type: 'reveal'; id: string }) => {
    requestToken.current += 1
    setViewRequest({ ...request, token: requestToken.current })
  }, [])

  const loadEntries = useCallback(async (signal?: AbortSignal) => {
    try {
      const entries = await fetchEntries(signal)
      if (signal?.aborted) return
      const index = buildIndex(entries)
      const current = locationRef.current
      if (current.kind === 'folder') {
        setExpanded(previous => revealFolder(index, previous, current.ref))
        requestView({ type: 'reveal', id: refId(current.ref) })
      }
      setData({ status: 'ready', index, refreshing: false, refreshError: null })
      setAnnouncement(`Loaded ${summary(index)}.`)
    } catch (error) {
      if (signal?.aborted) return
      setData({ status: 'error', message: errorMessage(error) })
      setAnnouncement('Loading failed.')
    }
  }, [requestView])

  useEffect(() => {
    const controller = new AbortController()
    void loadEntries(controller.signal)
    return () => controller.abort()
  }, [loadEntries])

  const retry = useCallback(() => {
    setData({ status: 'loading' })
    setAnnouncement('Loading the Pi and Claude fixture folders.')
    void loadEntries()
  }, [loadEntries])

  const refresh = useCallback(async () => {
    if (data.status !== 'ready' || data.refreshing) return
    setData({ ...data, refreshing: true })
    setAnnouncement('Refreshing the listing.')
    try {
      const entries = await fetchEntries()
      const index = buildIndex(entries)
      setExpanded(previous => pruneIds(index, previous))
      layout.prune(new Set(index.nodes.keys()))
      setData({ status: 'ready', index, refreshing: false, refreshError: null })
      const current = locationRef.current
      const missing = current.kind === 'folder' && !folderExists(index, current.ref)
      setAnnouncement(missing ? 'Refreshed. The selected folder no longer exists.' : `Refreshed: ${summary(index)}.`)
    } catch (error) {
      const message = errorMessage(error)
      setData(previous => (previous.status === 'ready' ? { ...previous, refreshing: false, refreshError: message } : previous))
      setAnnouncement('Refresh failed. Showing the previous listing, which may be outdated.')
    }
  }, [data, layout])

  const navigate = useCallback((ref: FolderRef | null, options: { replace?: boolean; reveal?: boolean } = {}) => {
    const pathname = folderToPathname(ref)
    if (window.location.pathname !== pathname) {
      window.history[options.replace ? 'replaceState' : 'pushState'](null, '', pathname)
    }
    setLocation(ref ? { kind: 'folder', ref } : { kind: 'home' })
    const index = indexRef.current
    if (ref && options.reveal && index) {
      setExpanded(previous => revealFolder(index, previous, ref))
      requestView({ type: 'reveal', id: refId(ref) })
    } else if (!ref) {
      requestView({ type: 'fit' })
    }
  }, [requestView])

  useEffect(() => {
    const onPopState = () => {
      const next = parsePathname(window.location.pathname)
      setLocation(next)
      const index = indexRef.current
      if (next.kind === 'folder' && index) {
        setExpanded(previous => revealFolder(index, previous, next.ref))
        requestView({ type: 'reveal', id: refId(next.ref) })
      }
    }
    window.addEventListener('popstate', onPopState)
    return () => window.removeEventListener('popstate', onPopState)
  }, [requestView])

  const index = data.status === 'ready' ? data.index : null
  const selectedRef = location.kind === 'folder' ? location.ref : null
  const selectedExists = index !== null && selectedRef !== null && folderExists(index, selectedRef)
  const selectedId = selectedExists && selectedRef ? refId(selectedRef) : null
  const visible = useMemo(() => (index ? visibleGraph(index, expanded) : { nodes: [], edges: [] }), [index, expanded])

  const select = useCallback((node: GraphNode) => {
    const ref = { source: node.source, path: node.path }
    if (sameRef(locationRef.current.kind === 'folder' ? locationRef.current.ref : null, ref)) return
    navigate(ref)
  }, [navigate])

  const toggleExpand = useCallback((node: GraphNode) => {
    if (!index) return
    if (expanded.has(node.id)) {
      setExpanded(collapseNode(index, expanded, node.id))
      const current = locationRef.current
      if (current.kind === 'folder' && descendantIds(index, node.id).includes(refId(current.ref))) {
        navigate({ source: node.source, path: node.path }, { replace: true })
      }
      setAnnouncement(`Collapsed ${node.name}.`)
    } else {
      setExpanded(new Set(expanded).add(node.id))
      setAnnouncement(`Expanded ${node.name}: ${describeCounts(childCounts(index, node.id))}`)
    }
  }, [index, expanded, navigate])

  const togglePin = useCallback((node: GraphNode) => {
    const wasPinned = layout.isPinned(node.id)
    layout.togglePin(node.id)
    setAnnouncement(`${wasPinned ? 'Unpinned' : 'Pinned'} ${node.name}.`)
  }, [layout])

  const reset = useCallback(() => {
    layout.reset()
    setExpanded(new Set())
    navigate(null)
    setAnnouncement('Reset: showing the Pi and Claude sources.')
  }, [layout, navigate])

  const toggleMode = useCallback(() => {
    setMode(previous => {
      const next = previous === 'graph' ? 'outline' : 'graph'
      setAnnouncement(next === 'outline' ? 'Outline view.' : 'Graph view.')
      return next
    })
  }, [])

  const ready = data.status === 'ready'
  const refreshing = data.status === 'ready' && data.refreshing
  const graphControlsEnabled = ready && mode === 'graph'

  let missingNotice: React.ReactNode = null
  if (index && location.kind === 'unknown-source') {
    missingNotice = <>Source “{location.name}” does not exist. Only the Pi and Claude sources are available.</>
  } else if (index && location.kind === 'malformed') {
    missingNotice = <>This link could not be read.</>
  } else if (index && selectedRef && !selectedExists) {
    missingNotice = <>Folder “{selectedRef.path || selectedRef.source}” was not found in {selectedRef.source}. It may have been renamed or removed.</>
  }

  return (
    <div className="app">
      <header className="app-header">
        <div className="app-title">
          <h1>MD Manager</h1>
          <p>Pi and Claude fixture folders as a containment graph. Read-only.</p>
        </div>
        <button type="button" className="button" onClick={() => void refresh()} disabled={!ready || refreshing} aria-busy={refreshing}>
          {refreshing ? 'Refreshing…' : 'Refresh'}
        </button>
      </header>

      <div className="visually-hidden" role="status" aria-live="polite">{announcement}</div>

      {data.status === 'ready' && data.refreshError && (
        <div className="banner banner-error" role="alert">
          Refresh failed: {data.refreshError} The graph still shows the previous listing, which may be outdated. Try Refresh again once the API and fixture folders are available.
        </div>
      )}

      <div className="navigation">
        <Breadcrumbs selected={selectedRef} onNavigate={ref => navigate(ref, { reveal: true })} />
        {missingNotice ? (
          <div className="missing" role="alert">
            <p>{missingNotice}</p>
            <p className="missing-links">
              {selectedRef && location.kind === 'folder'
                ? <a href={folderToPathname({ source: selectedRef.source, path: '' })} onClick={event => { event.preventDefault(); navigate({ source: selectedRef.source, path: '' }, { reveal: true }) }}>Go to the {selectedRef.source} root</a>
                : <>
                    <a href="/Pi" onClick={event => { event.preventDefault(); navigate({ source: 'Pi', path: '' }, { reveal: true }) }}>Go to the Pi root</a>
                    <a href="/Claude" onClick={event => { event.preventDefault(); navigate({ source: 'Claude', path: '' }, { reveal: true }) }}>Go to the Claude root</a>
                  </>}
              <a href="/" onClick={event => { event.preventDefault(); navigate(null) }}>Home</a>
            </p>
          </div>
        ) : (
          <p className="folder-info" data-testid="folder-info">
            {index && selectedId
              ? describeCounts(childCounts(index, selectedId))
              : 'Two sources: Pi and Claude. Select a source or folder to see what it contains.'}
          </p>
        )}
      </div>

      <div className="toolbar" role="toolbar" aria-label="Graph controls">
        <button type="button" className="button" onClick={() => canvasRef.current?.zoomIn()} disabled={!graphControlsEnabled} aria-label="Zoom in">+</button>
        <button type="button" className="button" onClick={() => canvasRef.current?.zoomOut()} disabled={!graphControlsEnabled} aria-label="Zoom out">−</button>
        <button type="button" className="button" onClick={() => canvasRef.current?.fit()} disabled={!graphControlsEnabled}>Fit</button>
        <button type="button" className="button" onClick={reset} disabled={!ready}>Reset</button>
        <button type="button" className="button" onClick={toggleMode} disabled={!ready} aria-pressed={mode === 'outline'}>Outline</button>
      </div>

      <main className="workspace" aria-busy={data.status === 'loading'}>
        {data.status === 'loading' && (
          <div className="placeholder">
            <p>Loading the Pi and Claude fixture folders…</p>
          </div>
        )}
        {data.status === 'error' && (
          <div className="placeholder" role="alert">
            <p>Unable to load the fixture folders. {data.message}</p>
            <p>Check that the API is running and both fixture folders are readable, then retry.</p>
            <button type="button" className="button" onClick={retry}>Retry</button>
          </div>
        )}
        {data.status === 'ready' && mode === 'graph' && (
          <GraphCanvas
            ref={canvasRef}
            layout={layout}
            index={data.index}
            nodes={visible.nodes}
            edges={visible.edges}
            expanded={expanded}
            selectedId={selectedId}
            viewRequest={viewRequest}
            onSelect={select}
            onToggleExpand={toggleExpand}
            onTogglePin={togglePin}
          />
        )}
        {data.status === 'ready' && mode === 'outline' && (
          <Outline index={data.index} expanded={expanded} selectedId={selectedId} onSelect={select} onToggleExpand={toggleExpand} />
        )}
      </main>

      {mode === 'graph' && (
        <footer className="legend" aria-label="Legend">
          <ul>
            <li><svg viewBox="-16 -16 32 32" aria-hidden="true"><circle className="legend-source" r="11" /></svg>Source</li>
            <li><svg viewBox="-16 -16 32 32" aria-hidden="true"><path className="legend-directory" d="M -12 -9 h 7 l 3 3 h 14 v 15 h -24 z" /></svg>Folder</li>
            <li><svg viewBox="-16 -16 32 32" aria-hidden="true"><path className="legend-file" d="M -7 -11 h 9 l 5 5 v 17 h -14 z" /></svg>Markdown file</li>
            <li><svg viewBox="-16 -16 32 32" aria-hidden="true"><line className="legend-edge" x1="-13" y1="0" x2="8" y2="0" markerEnd="url(#contains-arrow)" /><path className="legend-edge-arrow" d="M 7 -4 L 13 0 L 7 4 z" /></svg>Contains (parent → child)</li>
            <li><svg viewBox="-16 -16 32 32" aria-hidden="true"><circle className="legend-pin" r="9" /><path className="legend-pin-glyph" d="M -3 -4 h 6 l -1 4 h -4 z M 0 0 v 6" /></svg>Pinned (dragged or P)</li>
          </ul>
          <p>Keyboard: Tab moves through nodes in outline order, Enter selects, → expands, ← collapses, P pins or unpins.</p>
        </footer>
      )}
    </div>
  )
}

export default App

import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useLayoutEffect,
  useReducer,
  useRef,
  useState,
  type KeyboardEvent,
  type PointerEvent as ReactPointerEvent,
} from 'react'
import { childCounts, describeCounts, type GraphEdge, type GraphNode, type TreeIndex } from './model.ts'
import { GraphLayout, NODE_RADIUS, type Point } from './layout.ts'
import { wrapLabel } from './labels.ts'

export type ViewRequest = { token: number; type: 'fit' } | { token: number; type: 'reveal'; id: string }

export type GraphCanvasHandle = { zoomIn(): void; zoomOut(): void; fit(): void }

type Props = {
  layout: GraphLayout
  index: TreeIndex
  nodes: GraphNode[]
  edges: GraphEdge[]
  expanded: ReadonlySet<string>
  selectedId: string | null
  viewRequest: ViewRequest | null
  onSelect: (node: GraphNode) => void
  onToggleExpand: (node: GraphNode) => void
  onTogglePin: (node: GraphNode) => void
}

type View = { x: number; y: number; k: number }

const MIN_ZOOM = 0.15
const MAX_ZOOM = 3
const DRAG_THRESHOLD = 4
const FIT_PADDING = 70

function clampZoom(k: number) {
  return Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, k))
}

type NodeBox = { halfWidth: number; top: number; bottom: number }

/** Distance from a node's centre to the edge of its box (shape plus label) along a unit direction. */
function reach(box: NodeBox, ux: number, uy: number): number {
  const tx = Math.abs(ux) < 1e-6 ? Infinity : box.halfWidth / Math.abs(ux)
  const ty = Math.abs(uy) < 1e-6 ? Infinity : (uy > 0 ? box.bottom : box.top) / Math.abs(uy)
  return Math.min(tx, ty)
}

/** Edge endpoints trimmed so lines stop at the shapes and their labels, leaving room for the arrowhead. */
function edgeGeometry(parent: Point, child: Point, parentBox: NodeBox, childBox: NodeBox) {
  const dx = child.x - parent.x
  const dy = child.y - parent.y
  const length = Math.hypot(dx, dy) || 1
  const ux = dx / length
  const uy = dy / length
  const start = Math.min(reach(parentBox, ux, uy), length / 2)
  const end = Math.min(reach(childBox, -ux, -uy) + 5, length / 2)
  return { x1: parent.x + ux * start, y1: parent.y + uy * start, x2: child.x - ux * end, y2: child.y - uy * end }
}

function nodeBox(node: GraphNode, labelLines: number): NodeBox {
  const radius = NODE_RADIUS[node.kind]
  if (node.kind === 'source') return { halfWidth: radius, top: radius, bottom: radius }
  return { halfWidth: Math.max(radius, 36), top: radius, bottom: radius + 6 + labelLines * 13 }
}

export const GraphCanvas = forwardRef<GraphCanvasHandle, Props>(function GraphCanvas(props, ref) {
  const { layout, index, nodes, edges, expanded, selectedId, viewRequest, onSelect, onToggleExpand, onTogglePin } = props
  const svgRef = useRef<SVGSVGElement>(null)
  const [view, setView] = useState<View>({ x: 0, y: 0, k: 1 })
  const viewRef = useRef(view)
  useLayoutEffect(() => { viewRef.current = view }, [view])
  const [, rerender] = useReducer((count: number) => count + 1, 0)
  const pointers = useRef(new Map<number, Point>())
  const drag = useRef<{ id: string; pointerId: number; start: Point; offset: Point; moved: boolean } | null>(null)
  const suppressClick = useRef(false)

  useEffect(() => layout.subscribe(rerender), [layout])
  useLayoutEffect(() => { layout.sync(nodes, edges) }, [layout, nodes, edges])

  const size = useCallback(() => {
    const rect = svgRef.current?.getBoundingClientRect()
    return { width: rect?.width ?? 0, height: rect?.height ?? 0 }
  }, [])

  const toWorld = useCallback((clientX: number, clientY: number): Point => {
    const rect = svgRef.current!.getBoundingClientRect()
    const { x, y, k } = viewRef.current
    return { x: (clientX - rect.left - x) / k, y: (clientY - rect.top - y) / k }
  }, [])

  const zoomAt = useCallback((screen: Point, factor: number) => {
    setView(current => {
      const k = clampZoom(current.k * factor)
      const ratio = k / current.k
      return { k, x: screen.x - (screen.x - current.x) * ratio, y: screen.y - (screen.y - current.y) * ratio }
    })
  }, [])

  const fit = useCallback(() => {
    const { width, height } = size()
    const points = nodes.map(node => layout.node(node.id)).filter((node): node is NonNullable<typeof node> => node !== undefined)
    if (!width || !height || points.length === 0) return
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity
    for (const point of points) {
      minX = Math.min(minX, point.x - FIT_PADDING)
      maxX = Math.max(maxX, point.x + FIT_PADDING)
      minY = Math.min(minY, point.y - FIT_PADDING)
      maxY = Math.max(maxY, point.y + FIT_PADDING)
    }
    const k = clampZoom(Math.min(width / (maxX - minX), height / (maxY - minY), 1.25))
    const cx = (minX + maxX) / 2
    const cy = (minY + maxY) / 2
    setView({ k, x: width / 2 - cx * k, y: height / 2 - cy * k })
  }, [layout, nodes, size])

  const ensureVisible = useCallback((id: string) => {
    const node = layout.node(id)
    const { width, height } = size()
    if (!node || !width || !height) return
    setView(current => {
      const sx = node.x * current.k + current.x
      const sy = node.y * current.k + current.y
      const margin = 80
      if (sx > margin && sx < width - margin && sy > margin && sy < height - margin) return current
      return { ...current, x: width / 2 - node.x * current.k, y: height / 2 - node.y * current.k }
    })
  }, [layout, size])

  useImperativeHandle(ref, () => ({
    fit,
    zoomIn: () => { const { width, height } = size(); zoomAt({ x: width / 2, y: height / 2 }, 1.3) },
    zoomOut: () => { const { width, height } = size(); zoomAt({ x: width / 2, y: height / 2 }, 1 / 1.3) },
  }), [fit, size, zoomAt])

  // Fit once on mount; afterwards only explicit requests move the viewport.
  const mounted = useRef(false)
  useEffect(() => {
    if (mounted.current) return
    mounted.current = true
    fit()
  }, [fit])

  const handledRequest = useRef(0)
  useEffect(() => {
    if (!viewRequest || viewRequest.token === handledRequest.current) return
    handledRequest.current = viewRequest.token
    if (viewRequest.type === 'fit') fit()
    else ensureVisible(viewRequest.id)
  }, [viewRequest, fit, ensureVisible])

  useEffect(() => {
    const svg = svgRef.current
    if (!svg) return
    const onWheel = (event: WheelEvent) => {
      event.preventDefault()
      const rect = svg.getBoundingClientRect()
      const factor = Math.exp(-event.deltaY * (event.deltaMode === 1 ? 0.05 : 0.0025))
      zoomAt({ x: event.clientX - rect.left, y: event.clientY - rect.top }, factor)
    }
    svg.addEventListener('wheel', onWheel, { passive: false })
    return () => svg.removeEventListener('wheel', onWheel)
  }, [zoomAt])

  // ---- Background panning and pinch zoom ----
  const onBackgroundPointerDown = (event: ReactPointerEvent<SVGElement>) => {
    if (event.button !== 0 && event.pointerType === 'mouse') return
    pointers.current.set(event.pointerId, { x: event.clientX, y: event.clientY })
    event.currentTarget.setPointerCapture(event.pointerId)
  }
  const onBackgroundPointerMove = (event: ReactPointerEvent<SVGElement>) => {
    const previous = pointers.current.get(event.pointerId)
    if (!previous) return
    const next = { x: event.clientX, y: event.clientY }
    if (pointers.current.size === 1) {
      setView(current => ({ ...current, x: current.x + next.x - previous.x, y: current.y + next.y - previous.y }))
    } else if (pointers.current.size === 2) {
      const [a, b] = [...pointers.current.entries()]
      const other = a[0] === event.pointerId ? b[1] : a[1]
      const rect = svgRef.current!.getBoundingClientRect()
      const oldDistance = Math.hypot(previous.x - other.x, previous.y - other.y) || 1
      const newDistance = Math.hypot(next.x - other.x, next.y - other.y) || 1
      const oldMid = { x: (previous.x + other.x) / 2 - rect.left, y: (previous.y + other.y) / 2 - rect.top }
      const newMid = { x: (next.x + other.x) / 2 - rect.left, y: (next.y + other.y) / 2 - rect.top }
      setView(current => {
        const k = clampZoom(current.k * (newDistance / oldDistance))
        const ratio = k / current.k
        return { k, x: newMid.x - (oldMid.x - current.x) * ratio, y: newMid.y - (oldMid.y - current.y) * ratio }
      })
    }
    pointers.current.set(event.pointerId, next)
  }
  const onBackgroundPointerEnd = (event: ReactPointerEvent<SVGElement>) => {
    pointers.current.delete(event.pointerId)
  }

  // ---- Node dragging ----
  const onNodePointerDown = (node: GraphNode) => (event: ReactPointerEvent<SVGGElement>) => {
    if (event.button !== 0 && event.pointerType === 'mouse') return
    const position = layout.node(node.id)
    if (!position) return
    const world = toWorld(event.clientX, event.clientY)
    drag.current = {
      id: node.id,
      pointerId: event.pointerId,
      start: { x: event.clientX, y: event.clientY },
      offset: { x: position.x - world.x, y: position.y - world.y },
      moved: false,
    }
    suppressClick.current = false
    event.currentTarget.setPointerCapture(event.pointerId)
    event.stopPropagation()
  }
  const onNodePointerMove = (event: ReactPointerEvent<SVGGElement>) => {
    const current = drag.current
    if (!current || current.pointerId !== event.pointerId) return
    if (!current.moved) {
      if (Math.hypot(event.clientX - current.start.x, event.clientY - current.start.y) < DRAG_THRESHOLD) return
      current.moved = true
      suppressClick.current = true
    }
    const world = toWorld(event.clientX, event.clientY)
    layout.drag(current.id, { x: world.x + current.offset.x, y: world.y + current.offset.y })
  }
  const onNodePointerEnd = (event: ReactPointerEvent<SVGGElement>) => {
    const current = drag.current
    if (!current || current.pointerId !== event.pointerId) return
    drag.current = null
    if (current.moved) layout.endDrag()
  }
  const onNodeClick = (node: GraphNode) => () => {
    if (suppressClick.current) { suppressClick.current = false; return }
    if (node.kind !== 'file') onSelect(node)
  }
  const onNodeKeyDown = (node: GraphNode) => (event: KeyboardEvent<SVGGElement>) => {
    const isFolder = node.kind !== 'file'
    switch (event.key) {
      case 'Enter':
      case ' ':
        if (isFolder) onSelect(node)
        break
      case 'ArrowRight':
        if (isFolder && !expanded.has(node.id)) onToggleExpand(node)
        break
      case 'ArrowLeft':
        if (isFolder && expanded.has(node.id)) onToggleExpand(node)
        break
      case 'p':
      case 'P':
        onTogglePin(node)
        break
      default:
        return
    }
    event.preventDefault()
  }
  const stop = (event: ReactPointerEvent) => event.stopPropagation()
  const activate = (action: () => void) => (event: KeyboardEvent) => {
    if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); action() }
  }

  const showFileLabels = view.k >= 0.45
  const showFolderLabels = view.k >= 0.28
  const nodeById = new Map(nodes.map(node => [node.id, node]))
  const labelLines = (node: GraphNode) => {
    const shown = node.kind === 'source' || (node.kind === 'file' ? showFileLabels : showFolderLabels)
    return shown && node.kind !== 'source' ? wrapLabel(node.name).length : 0
  }

  return (
    <svg
      ref={svgRef}
      className="graph-canvas"
      role="group"
      aria-label="Directory graph"
      onPointerDown={onBackgroundPointerDown}
      onPointerMove={onBackgroundPointerMove}
      onPointerUp={onBackgroundPointerEnd}
      onPointerCancel={onBackgroundPointerEnd}
    >
      <defs>
        <marker id="contains-arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
          <path d="M 1 1 L 9 5 L 1 9 z" className="edge-arrow" />
        </marker>
      </defs>
      <rect className="graph-background" width="100%" height="100%" />
      <g transform={`translate(${view.x} ${view.y}) scale(${view.k})`}>
        <g className="edges" aria-hidden="true">
          {edges.map(edge => {
            const parent = layout.node(edge.parentId)
            const child = layout.node(edge.childId)
            const parentNode = nodeById.get(edge.parentId)
            const childNode = nodeById.get(edge.childId)
            if (!parent || !child || !parentNode || !childNode) return null
            const highlighted = edge.parentId === selectedId || edge.childId === selectedId
            const geometry = edgeGeometry(parent, child, nodeBox(parentNode, labelLines(parentNode)), nodeBox(childNode, labelLines(childNode)))
            return (
              <line
                key={edge.id}
                className={highlighted ? 'edge edge-highlight' : 'edge'}
                data-edge-parent={edge.parentId}
                data-edge-child={edge.childId}
                {...geometry}
                markerEnd="url(#contains-arrow)"
              />
            )
          })}
        </g>
        <g className="nodes">
          {nodes.map(node => {
            const position = layout.node(node.id)
            if (!position) return null
            const radius = NODE_RADIUS[node.kind]
            const isFolder = node.kind !== 'file'
            const isExpanded = isFolder && expanded.has(node.id)
            const isSelected = node.id === selectedId
            const pinned = layout.isPinned(node.id)
            const counts = isFolder ? childCounts(index, node.id) : null
            const isEmpty = counts !== null && counts.directories + counts.files === 0
            const description = counts ? describeCounts(counts) : 'Markdown file'
            const label = isFolder
              ? `${node.name}, ${node.kind === 'source' ? 'source folder' : 'folder'}, ${description}${pinned ? ', pinned' : ''}`
              : `${node.name}, Markdown file${pinned ? ', pinned' : ''}`
            const showLabel = node.kind === 'source' || (node.kind === 'file' ? showFileLabels : showFolderLabels)
            const lines = node.kind === 'source' ? [node.name] : wrapLabel(node.name)
            const classes = ['node', `node-${node.kind}`, isSelected ? 'is-selected' : '', pinned ? 'is-pinned' : '']
            return (
              <g key={node.id} className={classes.join(' ').trim()} transform={`translate(${position.x} ${position.y})`} data-node-id={node.id} data-node-kind={node.kind}>
                <g
                  className="node-body"
                  role={isFolder ? 'button' : 'group'}
                  tabIndex={0}
                  aria-label={label}
                  aria-pressed={isFolder ? isSelected : undefined}
                  onPointerDown={onNodePointerDown(node)}
                  onPointerMove={onNodePointerMove}
                  onPointerUp={onNodePointerEnd}
                  onPointerCancel={onNodePointerEnd}
                  onClick={onNodeClick(node)}
                  onKeyDown={onNodeKeyDown(node)}
                >
                  <title>{label}</title>
                  <circle className="focus-ring" r={radius + 6} />
                  {node.kind === 'source' && <circle className="shape" r={radius} />}
                  {node.kind === 'directory' && <path className="shape" d="M -20 -15 h 12 l 4 4 h 24 v 26 h -40 z" />}
                  {node.kind === 'file' && (
                    <>
                      <path className="shape" d="M -10 -14 h 14 l 6 6 v 22 h -20 z" />
                      <path className="shape-detail" d="M 4 -14 v 6 h 6 M -6 0 h 12 M -6 6 h 12" />
                    </>
                  )}
                  {showLabel && (
                    <text className="label" textAnchor="middle" y={node.kind === 'source' ? 5 : radius + 16} aria-hidden="true">
                      {lines.map((line, i) => <tspan key={i} x="0" dy={i === 0 ? 0 : 13}>{line}</tspan>)}
                    </text>
                  )}
                  {isExpanded && isEmpty && (
                    <text className="empty-tag" textAnchor="middle" y={radius + 16 + lines.length * 13} aria-hidden="true">empty</text>
                  )}
                </g>
                {isFolder && (
                  <g
                    className="node-toggle"
                    role="button"
                    tabIndex={0}
                    aria-expanded={isExpanded}
                    aria-label={`${isExpanded ? 'Collapse' : 'Expand'} ${node.name}`}
                    transform={`translate(${radius * 0.85} ${-radius * 0.85})`}
                    onPointerDown={stop}
                    onClick={() => onToggleExpand(node)}
                    onKeyDown={activate(() => onToggleExpand(node))}
                  >
                    <circle r={9} />
                    <path d={isExpanded ? 'M -4 0 h 8' : 'M -4 0 h 8 M 0 -4 v 8'} />
                  </g>
                )}
                {pinned && (
                  <g
                    className="node-pin"
                    role="button"
                    tabIndex={0}
                    aria-label={`Unpin ${node.name}`}
                    transform={`translate(${-radius * 0.85} ${-radius * 0.85})`}
                    onPointerDown={stop}
                    onClick={() => onTogglePin(node)}
                    onKeyDown={activate(() => onTogglePin(node))}
                  >
                    <circle r={8} />
                    <path d="M -3 -3 h 6 l -1 4 h -4 z M 0 1 v 5" />
                  </g>
                )}
              </g>
            )
          })}
        </g>
      </g>
    </svg>
  )
})

import {
  forceCollide,
  forceLink,
  forceManyBody,
  forceSimulation,
  forceX,
  forceY,
  type Simulation,
  type SimulationLinkDatum,
  type SimulationNodeDatum,
} from 'd3-force'
import type { GraphEdge, GraphNode, NodeKind, Source } from './model.ts'

export type Point = { x: number; y: number }

export type SimNode = SimulationNodeDatum & {
  id: string
  kind: NodeKind
  source: Source
  parentId: string | null
  x: number
  y: number
}

type SimLink = SimulationLinkDatum<SimNode> & { source: SimNode; target: SimNode }

/** Drawn radius of each node type; also used to trim edges. */
export const NODE_RADIUS: Record<NodeKind, number> = { source: 30, directory: 20, file: 14 }
/** Personal space for collision avoidance, leaving room for the label below the shape. */
const COLLIDE_RADIUS: Record<NodeKind, number> = { source: 54, directory: 42, file: 34 }
const CHARGE: Record<NodeKind, number> = { source: -700, directory: -380, file: -160 }
/** Each source cluster is gently pulled to its own side so Pi and Claude stay recognisable. */
const SOURCE_ANCHOR: Record<Source, Point> = { Pi: { x: -180, y: 0 }, Claude: { x: 180, y: 0 } }
const ALPHA_MIN = 0.02
const MAX_SYNC_TICKS = 400

function linkDistance(link: SimLink): number {
  if (link.source.kind === 'source') return 130
  return link.target.kind === 'file' ? 80 : 105
}

/**
 * Owns the force simulation and every node position for the session. Positions of hidden nodes are
 * remembered so that expanding, collapsing and refreshing never rearranges unrelated parts of the graph.
 */
export class GraphLayout {
  private readonly nodes = new Map<string, SimNode>()
  private readonly pinned = new Set<string>()
  private readonly simulation: Simulation<SimNode, SimLink>
  private readonly listeners = new Set<() => void>()
  private visibleIds: string[] = []
  private hasLaidOut = false
  private synchronous: boolean

  constructor(options: { synchronous: boolean }) {
    this.synchronous = options.synchronous
    this.simulation = forceSimulation<SimNode>([])
      .stop()
      .alphaMin(ALPHA_MIN)
      .alphaDecay(0.05)
      .force('link', forceLink<SimNode, SimLink>([]).id(node => node.id).distance(linkDistance).strength(0.9))
      .force('charge', forceManyBody<SimNode>().strength(node => CHARGE[node.kind]).distanceMax(520))
      .force('collide', forceCollide<SimNode>().radius(node => COLLIDE_RADIUS[node.kind]).strength(0.9).iterations(2))
      .force('x', forceX<SimNode>(node => SOURCE_ANCHOR[node.source].x).strength(0.03))
      .force('y', forceY<SimNode>(node => SOURCE_ANCHOR[node.source].y).strength(0.03))
      .on('tick', () => this.notify())
      .on('end', () => this.notify())
  }

  /** Synchronous mode settles the layout instantly (reduced motion, tests) instead of animating ticks. */
  setSynchronous(value: boolean) {
    this.synchronous = value
  }

  subscribe(listener: () => void): () => void {
    this.listeners.add(listener)
    return () => { this.listeners.delete(listener) }
  }

  private notify() {
    for (const listener of this.listeners) listener()
  }

  node(id: string): SimNode | undefined {
    return this.nodes.get(id)
  }

  isPinned(id: string): boolean {
    return this.pinned.has(id)
  }

  /** Aligns the simulation with the currently visible nodes. New nodes appear beside their parent. */
  sync(visible: readonly GraphNode[], edges: readonly GraphEdge[]) {
    const previous = this.visibleIds
    const nextIds = visible.map(node => node.id)
    const unchanged = previous.length === nextIds.length && previous.every((id, i) => id === nextIds[i])
    if (unchanged && this.hasLaidOut) return
    const previouslyVisible = new Set(previous)
    const siblingCounter = new Map<string, number>()
    const simNodes: SimNode[] = []
    for (const node of visible) {
      let sim = this.nodes.get(node.id)
      if (!sim) {
        sim = { id: node.id, kind: node.kind, source: node.source, parentId: node.parentId, x: 0, y: 0 }
        this.nodes.set(node.id, sim)
        this.place(sim, siblingCounter)
      } else if (!previouslyVisible.has(node.id) && !this.pinned.has(node.id)) {
        this.place(sim, siblingCounter)
      }
      simNodes.push(sim)
    }
    const links: SimLink[] = []
    for (const edge of edges) {
      const source = this.nodes.get(edge.parentId)
      const target = this.nodes.get(edge.childId)
      if (source && target) links.push({ source, target })
    }
    this.visibleIds = nextIds
    this.simulation.nodes(simNodes)
    this.simulation.force<ReturnType<typeof forceLink<SimNode, SimLink>>>('link')!.links(links)
    // The very first layout has nothing to transition from, so it always settles instantly.
    this.run(this.hasLaidOut ? 0.6 : 1, !this.hasLaidOut)
    this.hasLaidOut = true
  }

  /** Deterministic placement: fan children out on the side of the parent facing away from the grandparent. */
  private place(sim: SimNode, siblingCounter: Map<string, number>) {
    if (sim.parentId === null) {
      const anchor = SOURCE_ANCHOR[sim.source]
      sim.x = anchor.x
      sim.y = anchor.y
      return
    }
    const parent = this.nodes.get(sim.parentId)
    if (!parent) return
    const index = siblingCounter.get(parent.id) ?? 0
    siblingCounter.set(parent.id, index + 1)
    const grandparent = parent.parentId ? this.nodes.get(parent.parentId) : undefined
    const base = grandparent ? Math.atan2(parent.y - grandparent.y, parent.x - grandparent.x) : -Math.PI / 2
    const angle = base + (index * 2.399963) // golden angle keeps siblings spread without randomness
    const distance = 60 + (index % 3) * 18
    sim.x = parent.x + Math.cos(angle) * distance
    sim.y = parent.y + Math.sin(angle) * distance
    sim.vx = 0
    sim.vy = 0
  }

  private run(alpha: number, forceSynchronous = false) {
    this.simulation.alpha(alpha)
    if (this.synchronous || forceSynchronous) {
      this.simulation.stop()
      for (let i = 0; i < MAX_SYNC_TICKS && this.simulation.alpha() > ALPHA_MIN; i += 1) this.simulation.tick()
      this.notify()
    } else {
      this.simulation.restart()
    }
  }

  /** Moves a node while it is being dragged. The node becomes pinned; the rest of the graph waits. */
  drag(id: string, point: Point) {
    const sim = this.nodes.get(id)
    if (!sim) return
    this.simulation.stop()
    sim.x = sim.fx = point.x
    sim.y = sim.fy = point.y
    sim.vx = 0
    sim.vy = 0
    this.pinned.add(id)
    this.notify()
  }

  /** After a drop, neighbours settle around the pinned node. */
  endDrag() {
    this.run(0.3)
  }

  pin(id: string) {
    const sim = this.nodes.get(id)
    if (!sim) return
    sim.fx = sim.x
    sim.fy = sim.y
    this.pinned.add(id)
    this.notify()
  }

  unpin(id: string) {
    const sim = this.nodes.get(id)
    if (!sim || !this.pinned.has(id)) return
    sim.fx = null
    sim.fy = null
    this.pinned.delete(id)
    this.run(0.3)
  }

  togglePin(id: string) {
    if (this.pinned.has(id)) this.unpin(id)
    else this.pin(id)
  }

  /** Forget nodes that no longer exist after a refresh. */
  prune(existing: ReadonlySet<string>) {
    for (const id of this.nodes.keys()) {
      if (!existing.has(id)) {
        this.nodes.delete(id)
        this.pinned.delete(id)
      }
    }
  }

  /** Clears pins and remembered positions. */
  reset() {
    this.simulation.stop()
    this.nodes.clear()
    this.pinned.clear()
    this.visibleIds = []
    this.hasLaidOut = false
    this.notify()
  }

  dispose() {
    this.simulation.stop()
  }
}

/**
 * Pure graph model: builds a containment tree from the flat /api/entries listing and
 * derives what is visible for a given expansion state. No DOM or layout concerns live here.
 */

export type Source = 'Pi' | 'Claude'
export const SOURCES: readonly Source[] = ['Pi', 'Claude']
export type EntryKind = 'directory' | 'file'
export type Entry = { source: Source; path: string; kind: EntryKind }
export type NodeKind = 'source' | 'directory' | 'file'

/** A source root (path '') or a directory inside it. */
export type FolderRef = { source: Source; path: string }

export type GraphNode = {
  id: string
  source: Source
  path: string
  name: string
  kind: NodeKind
  parentId: string | null
  depth: number
}

export type GraphEdge = { id: string; parentId: string; childId: string }

export type TreeIndex = {
  nodes: Map<string, GraphNode>
  /** Immediate children in display order: directories first, then files, each alphabetical. */
  children: Map<string, GraphNode[]>
}

export type ChildCounts = { directories: number; files: number }

export function isSource(value: string): value is Source {
  return value === 'Pi' || value === 'Claude'
}

export function nodeId(source: Source, path: string): string {
  return path ? `${source}/${path}` : source
}

export function refId(ref: FolderRef): string {
  return nodeId(ref.source, ref.path)
}

export function sameRef(a: FolderRef | null, b: FolderRef | null): boolean {
  return a === b || (a !== null && b !== null && a.source === b.source && a.path === b.path)
}

function baseName(path: string): string {
  return path.slice(path.lastIndexOf('/') + 1)
}

function parentPath(path: string): string {
  const index = path.lastIndexOf('/')
  return index === -1 ? '' : path.slice(0, index)
}

const collator = new Intl.Collator('en', { numeric: true, sensitivity: 'base' })

function compareNodes(a: GraphNode, b: GraphNode): number {
  if (a.kind !== b.kind) return a.kind === 'directory' ? -1 : 1
  return collator.compare(a.name, b.name) || (a.name < b.name ? -1 : a.name > b.name ? 1 : 0)
}

/** Builds the containment index. Parents are created implicitly if the listing omits them. */
export function buildIndex(entries: readonly Entry[]): TreeIndex {
  const nodes = new Map<string, GraphNode>()
  for (const source of SOURCES) {
    nodes.set(source, { id: source, source, path: '', name: source, kind: 'source', parentId: null, depth: 0 })
  }
  function ensure(source: Source, path: string, kind: NodeKind): GraphNode {
    const id = nodeId(source, path)
    const existing = nodes.get(id)
    if (existing) return existing
    const parent = path.includes('/') ? ensure(source, parentPath(path), 'directory') : nodes.get(source)!
    const node: GraphNode = { id, source, path, name: baseName(path), kind, parentId: parent.id, depth: parent.depth + 1 }
    nodes.set(id, node)
    return node
  }
  for (const entry of entries) {
    if (!isSource(entry.source) || !entry.path || entry.path.split('/').some(segment => segment === '')) continue
    ensure(entry.source, entry.path, entry.kind === 'directory' ? 'directory' : 'file')
  }
  const children = new Map<string, GraphNode[]>()
  for (const node of nodes.values()) {
    if (node.parentId === null) continue
    const siblings = children.get(node.parentId) ?? []
    siblings.push(node)
    children.set(node.parentId, siblings)
  }
  for (const siblings of children.values()) siblings.sort(compareNodes)
  return { nodes, children }
}

export function childrenOf(index: TreeIndex, id: string): GraphNode[] {
  return index.children.get(id) ?? []
}

export function childCounts(index: TreeIndex, id: string): ChildCounts {
  const counts = { directories: 0, files: 0 }
  for (const child of childrenOf(index, id)) {
    if (child.kind === 'file') counts.files += 1
    else counts.directories += 1
  }
  return counts
}

export function describeCounts({ directories, files }: ChildCounts): string {
  if (directories + files === 0) return 'This folder is empty.'
  const parts = [
    `${directories} ${directories === 1 ? 'folder' : 'folders'}`,
    `${files} ${files === 1 ? 'Markdown file' : 'Markdown files'}`,
  ]
  return parts.join(', ')
}

/** Ids of every descendant of `id`, depth-first. */
export function descendantIds(index: TreeIndex, id: string): string[] {
  const result: string[] = []
  const stack = [...childrenOf(index, id)]
  while (stack.length) {
    const node = stack.pop()!
    result.push(node.id)
    stack.push(...childrenOf(index, node.id))
  }
  return result
}

/** Ids of the source and every ancestor directory of `node`, outermost first (excluding the node itself). */
export function ancestorIds(node: GraphNode): string[] {
  const ids: string[] = []
  if (node.kind === 'source') return ids
  ids.push(node.source)
  const segments = node.path.split('/')
  for (let i = 1; i < segments.length; i += 1) ids.push(nodeId(node.source, segments.slice(0, i).join('/')))
  return ids
}

/** Visible nodes in keyboard/DOM order (pre-order: Pi subtree, then Claude subtree), and their containment edges. */
export function visibleGraph(index: TreeIndex, expanded: ReadonlySet<string>): { nodes: GraphNode[]; edges: GraphEdge[] } {
  const nodes: GraphNode[] = []
  const edges: GraphEdge[] = []
  function visit(node: GraphNode) {
    nodes.push(node)
    if (node.kind === 'file' || !expanded.has(node.id)) return
    for (const child of childrenOf(index, node.id)) {
      edges.push({ id: child.id, parentId: node.id, childId: child.id })
      visit(child)
    }
  }
  for (const source of SOURCES) visit(index.nodes.get(source)!)
  return { nodes, edges }
}

/** Collapsing hides every descendant and forgets their expansion state. */
export function collapseNode(index: TreeIndex, expanded: ReadonlySet<string>, id: string): Set<string> {
  const next = new Set(expanded)
  next.delete(id)
  for (const descendant of descendantIds(index, id)) next.delete(descendant)
  return next
}

/** Expands the ancestor chain and the folder itself so it is visible, leaving other branches alone. */
export function revealFolder(index: TreeIndex, expanded: ReadonlySet<string>, ref: FolderRef): Set<string> {
  const node = index.nodes.get(refId(ref))
  if (!node || node.kind === 'file') return new Set(expanded)
  const next = new Set(expanded)
  for (const id of ancestorIds(node)) next.add(id)
  next.add(node.id)
  return next
}

/** Drops ids that no longer exist after a refresh. */
export function pruneIds(index: TreeIndex, ids: ReadonlySet<string>): Set<string> {
  return new Set([...ids].filter(id => index.nodes.has(id)))
}

export function folderExists(index: TreeIndex, ref: FolderRef | null): boolean {
  if (ref === null) return true
  const node = index.nodes.get(refId(ref))
  return node !== undefined && node.kind !== 'file'
}

// ---- URLs ---------------------------------------------------------------------------------------

/** Encodes the selected folder as a pathname, encoding every segment so spaces, #, ? and % survive. */
export function folderToPathname(ref: FolderRef | null): string {
  if (ref === null) return '/'
  const segments = ref.path ? [ref.source, ...ref.path.split('/')] : [ref.source]
  return `/${segments.map(encodeURIComponent).join('/')}`
}

export type ParsedLocation =
  | { kind: 'home' }
  | { kind: 'folder'; ref: FolderRef }
  | { kind: 'unknown-source'; name: string }
  | { kind: 'malformed' }

export function parsePathname(pathname: string): ParsedLocation {
  const raw = pathname.split('/').filter(segment => segment !== '')
  if (raw.length === 0) return { kind: 'home' }
  let segments: string[]
  try {
    segments = raw.map(decodeURIComponent)
  } catch {
    return { kind: 'malformed' }
  }
  const [source, ...rest] = segments
  if (!isSource(source)) return { kind: 'unknown-source', name: source }
  return { kind: 'folder', ref: { source, path: rest.join('/') } }
}

export type Breadcrumb = { label: string; ref: FolderRef | null; id: string }

/** Home, then the source, then one crumb per directory segment. */
export function breadcrumbsFor(ref: FolderRef | null): Breadcrumb[] {
  const crumbs: Breadcrumb[] = [{ label: 'Home', ref: null, id: 'home' }]
  if (ref === null) return crumbs
  crumbs.push({ label: ref.source, ref: { source: ref.source, path: '' }, id: ref.source })
  if (!ref.path) return crumbs
  const segments = ref.path.split('/')
  for (let i = 0; i < segments.length; i += 1) {
    const path = segments.slice(0, i + 1).join('/')
    crumbs.push({ label: segments[i], ref: { source: ref.source, path }, id: nodeId(ref.source, path) })
  }
  return crumbs
}

import { childCounts, childrenOf, describeCounts, SOURCES, type GraphNode, type TreeIndex } from './model.ts'

type Props = {
  index: TreeIndex
  expanded: ReadonlySet<string>
  selectedId: string | null
  onSelect: (node: GraphNode) => void
  onToggleExpand: (node: GraphNode) => void
}

/** Accessible replacement for the graph: the same tree, expansion state and selection as nested lists. */
export function Outline({ index, expanded, selectedId, onSelect, onToggleExpand }: Props) {
  function renderFolder(node: GraphNode) {
    const isExpanded = expanded.has(node.id)
    const counts = childCounts(index, node.id)
    const children = childrenOf(index, node.id)
    return (
      <li key={node.id} className={`outline-item outline-${node.kind}`} data-node-id={node.id}>
        <div className="outline-row">
          <button
            type="button"
            className="outline-toggle"
            aria-expanded={isExpanded}
            aria-label={`${isExpanded ? 'Collapse' : 'Expand'} ${node.name}`}
            onClick={() => onToggleExpand(node)}
          >
            <svg viewBox="0 0 10 10" width="10" height="10" aria-hidden="true">
              <path d={isExpanded ? 'M 1 3 L 5 7 L 9 3' : 'M 3 1 L 7 5 L 3 9'} />
            </svg>
          </button>
          <button
            type="button"
            className="outline-name"
            aria-current={node.id === selectedId ? 'true' : undefined}
            onClick={() => onSelect(node)}
          >
            <span className="outline-icon" aria-hidden="true">{node.kind === 'source' ? '◎' : '▰'}</span>
            <span>{node.name}</span>
            <span className="visually-hidden">, {node.kind === 'source' ? 'source folder' : 'folder'}</span>
          </button>
          <span className="outline-counts">{describeCounts(counts)}</span>
        </div>
        {isExpanded && (
          <ul className="outline-list">
            {children.length === 0
              ? <li className="outline-empty">This folder is empty.</li>
              : children.map(child => (child.kind === 'file' ? renderFile(child) : renderFolder(child)))}
          </ul>
        )}
      </li>
    )
  }

  function renderFile(node: GraphNode) {
    return (
      <li key={node.id} className="outline-item outline-file" data-node-id={node.id}>
        <div className="outline-row">
          <span className="outline-icon" aria-hidden="true">▤</span>
          <span>{node.name}</span>
          <span className="outline-counts">Markdown file</span>
        </div>
      </li>
    )
  }

  return (
    <nav className="outline" aria-label="Directory outline">
      <ul className="outline-list outline-root">
        {SOURCES.map(source => renderFolder(index.nodes.get(source)!))}
      </ul>
    </nav>
  )
}

